// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496));
        vm.assume(caller != address(this));
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || c.owner() == address(0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496), "setOwner called by non-admin should revert or leave owner unchanged");
    }
}
